<?php

/* @autogenerated */
declare(strict_types=1);

use Civi\Lughauth\Features\Access\UserProfile\Domain\ValueObject\Accessor\UserProfileUpdatedAtAccessor;
use PHPUnit\Framework\TestCase;

/**
 * Unit tests for the UserProfileUpdatedAtAccessor trait.
 *
 * Covers null default, string/VO assignment via withUpdatedAt,
 * getUpdatedAt/updatedAt accessors, and isUpdatedAtChanged with/without original.
 */
class UserProfileUpdatedAtAccessorUnitTest extends TestCase
{
    /**
     * Asserts that withUpdatedAt creates a new instance with the UpdatedAt set
     * from a string value, and getUpdatedAt returns the primitive string.
     */
    public function testWithUpdatedAtFromString(): void
    {
        // Arrange
        $holder = new ImplWithUserProfileUpdatedAtAccessorUnitTest();

        // Act
        $result = $holder->withUpdatedAt('one');

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals('one', $result->getUpdatedAt());
    }
    /**
     * Asserts that withupdatedAt has access to the value object
     * from a string value, and getUpdatedAt returns the primitive string.
     */
    public function testWithUpdatedAtFromValueObject(): void
    {
        // Arrange
        $holder = new ImplWithUserProfileUpdatedAtAccessorUnitTest();

        // Act
        $result = $holder->withUpdatedAt('one');

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals('one', $result->updatedAt()->value());
    }
    public function testChangedUpdatedAt(): void
    {
        // Arrange
        $holder = new ImplWithUserProfileUpdatedAtAccessorUnitTest();
        $original = $holder->withUpdatedAt('one');
        $same = $holder->withUpdatedAt('one');
        $modified = $holder->withUpdatedAt('other');

        // Act
        $unchanged = $holder->isUpdatedAtChanged();
        $withSame = $original->isUpdatedAtChanged($same);
        $withDiferent = $original->isUpdatedAtChanged($modified);

        // Assert
        $this->assertFalse($unchanged);
        $this->assertFalse($withSame);
        $this->assertTrue($withDiferent);
    }
}
class ImplWithUserProfileUpdatedAtAccessorUnitTest
{
    use UserProfileUpdatedAtAccessor;
}
